import { ThemeProvider } from 'next-themes'
import 'tally-charts/theme.css'

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" suppressHydrationWarning>
      <body>
        <ThemeProvider attribute={['class', 'data-ch-theme']}>{children}</ThemeProvider>
      </body>
    </html>
  )
}

import { cookies } from 'next/headers'
import 'tally-charts/theme.css'

export default async function RootLayout({ children }: { children: React.ReactNode }) {
  const stored = (await cookies()).get('theme')?.value
  const theme = stored === 'light' || stored === 'dark' ? stored : undefined

  return (
    // No cookie yet: no attribute, so the charts follow the system setting.
    <html lang="en" className={theme} data-ch-theme={theme}>
      <body>{children}</body>
    </html>
  )
}

